import Foundation
import CryptoKit

// MARK: - Blockchain Smart Contract with Graceful Shutdown

actor TransactionProcessor {
    private var nonces: [String: UInt64] = [:]
    private var balances: [String: UInt64] = [:]
    private var processedSignatures: Set<String> = []
    private var isShuttingDown = false
    private var pendingDrain: [SignedTransaction] = []
    private let maxPendingDrain = 50

    struct SignedTransaction {
        let from: String
        let to: String
        let amount: UInt64
        let nonce: UInt64
        let signature: Data
        let chainId: UInt32
    }

    func deposit(address: String, amount: UInt64) {
        balances[address, default: 0] += amount
    }

    func getBalance(address: String) -> UInt64 {
        return balances[address, default: 0]
    }

    func initiateGracefulShutdown() {
        isShuttingDown = true
    }

    func isInShutdown() -> Bool {
        return isShuttingDown
    }

    private func computeTransactionHash(_ tx: SignedTransaction) -> String {
        var hasher = SHA256()
        hasher.update(data: Data(tx.from.utf8))
        hasher.update(data: Data(tx.to.utf8))
        withUnsafeBytes(of: tx.amount.bigEndian) { hasher.update(bufferPointer: $0) }
        withUnsafeBytes(of: tx.nonce.bigEndian) { hasher.update(bufferPointer: $0) }
        withUnsafeBytes(of: tx.chainId.bigEndian) { hasher.update(bufferPointer: $0) }
        let digest = hasher.finalize()
        return digest.map { String(format: "%02x", $0) }.joined()
    }

    private func computeSignatureId(_ tx: SignedTransaction) -> String {
        // Signature ID for replay protection uses signature bytes
        return tx.signature.base64EncodedString()
    }

    private func verifySignature(_ tx: SignedTransaction, publicKey: Curve25519.Signing.PublicKey) -> Bool {
        let hash = computeTransactionHash(tx)
        guard let hashData = hash.data(using: .utf8) else { return false }
        return publicKey.isValidSignature(tx.signature, for: hashData)
    }

    func processTransaction(_ tx: SignedTransaction, publicKey: Curve25519.Signing.PublicKey) -> Result<String, TransactionError> {
        // During graceful shutdown, queue transactions for drain processing
        if isShuttingDown {
            return enqueueDrainTransaction(tx, publicKey: publicKey)
        }

        return executeTransaction(tx, publicKey: publicKey)
    }

    private func executeTransaction(_ tx: SignedTransaction, publicKey: Curve25519.Signing.PublicKey) -> Result<String, TransactionError> {
        // Step 1: Verify signature
        guard verifySignature(tx, publicKey: publicKey) else {
            return .failure(.invalidSignature)
        }

        // Step 2: Check replay protection
        let sigId = computeSignatureId(tx)
        guard !processedSignatures.contains(sigId) else {
            return .failure(.replayDetected)
        }

        // Step 3: Verify nonce ordering
        let expectedNonce = nonces[tx.from, default: 0]
        guard tx.nonce == expectedNonce else {
            return .failure(.invalidNonce)
        }

        // Step 4: Check balance
        guard balances[tx.from, default: 0] >= tx.amount else {
            return .failure(.insufficientBalance)
        }

        // Step 5: Execute transfer
        balances[tx.from, default: 0] -= tx.amount
        balances[tx.to, default: 0] += tx.amount
        nonces[tx.from] = expectedNonce + 1
        processedSignatures.insert(sigId)

        return .success(computeTransactionHash(tx))
    }

    private func enqueueDrainTransaction(_ tx: SignedTransaction, publicKey: Curve25519.Signing.PublicKey) -> Result<String, TransactionError> {
        // During shutdown, we validate and queue
        guard verifySignature(tx, publicKey: publicKey) else {
            return .failure(.invalidSignature)
        }

        guard pendingDrain.count < maxPendingDrain else {
            return .failure(.shutdownQueueFull)
        }

        pendingDrain.append(tx)
        return .success("queued:\(computeTransactionHash(tx))")
    }

    func drainPendingTransactions(publicKeys: [String: Curve25519.Signing.PublicKey]) -> [Result<String, TransactionError>] {
        var results: [Result<String, TransactionError>] = []

        // Process queued transactions - replay check uses separate drain context
        var drainProcessedSigs: Set<String> = []

        for tx in pendingDrain {
            guard let pubKey = publicKeys[tx.from] else {
                results.append(.failure(.unknownSender))
                continue
            }

            let sigId = computeSignatureId(tx)

            // Check within drain batch for duplicates
            guard !drainProcessedSigs.contains(sigId) else {
                results.append(.failure(.replayDetected))
                continue
            }

            // Verify nonce
            let expectedNonce = nonces[tx.from, default: 0]
            guard tx.nonce == expectedNonce else {
                results.append(.failure(.invalidNonce))
                continue
            }

            // Check balance
            guard balances[tx.from, default: 0] >= tx.amount else {
                results.append(.failure(.insufficientBalance))
                continue
            }

            // Execute
            balances[tx.from, default: 0] -= tx.amount
            balances[tx.to, default: 0] += tx.amount
            nonces[tx.from] = expectedNonce + 1
            drainProcessedSigs.insert(sigId)
            // Note: processedSignatures is NOT updated here during drain

            results.append(.success(computeTransactionHash(tx)))
        }

        pendingDrain.removeAll()
        isShuttingDown = false
        return results
    }
}

enum TransactionError: Error {
    case invalidSignature
    case replayDetected
    case invalidNonce
    case insufficientBalance
    case shutdownQueueFull
    case unknownSender
}

// MARK: - Shutdown Coordinator

class ShutdownCoordinator {
    let processor: TransactionProcessor
    private var shutdownComplete = false

    init(processor: TransactionProcessor) {
        self.processor = processor
    }

    func performGracefulShutdown(publicKeys: [String: Curve25519.Signing.PublicKey]) async -> [Result<String, TransactionError>] {
        await processor.initiateGracefulShutdown()

        // Allow brief window for in-flight transactions
        try? await Task.sleep(nanoseconds: 100_000_000)

        let results = await processor.drainPendingTransactions(publicKeys: publicKeys)
        shutdownComplete = true
        return results
    }
}
